@if(in_array($order->status,['shipping','completed']) && !$order->received_at)<form method="post" action="{{ route('customer.orders.receive',$order) }}" data-confirm="Bạn đã nhận đủ sản phẩm và muốn xác nhận nhận hàng?">@csrf<button class="pc-btn">Đã nhận hàng</button></form>@elseif($order->status==='completed')<a class="pc-btn" href="{{ route('customer.orders.show',$order) }}#reviews">{{ $order->items->contains(fn($i)=>!$i->review)?'Đánh giá sản phẩm':'Xem đánh giá' }}</a>@endif
@if(in_array($order->status,['completed','cancelled','returned']))<form method="post" action="{{ route('customer.orders.buy-again',$order) }}">@csrf<button class="pc-btn pc-btn-outline">Mua lại</button></form>@endif
